function recalc(fill=false){let c=CLASSES[player.classId],s={...c.stats},b={atkMin:s.str*2+player.level*1.5,atkMax:s.str*2.7+player.level*2,matk:s.int*2.6+player.level*1.8,def:s.vit*1.2+player.level*.7,mdef:s.spi*1.15+player.level*.65,crit:4+s.dex*.55,accuracy:78+s.dex*.7,evasion:s.dex*.45,speed:6.2,hp:0,mp:0};Object.values(player.equipment).filter(Boolean).forEach(o=>{let d=itemDef(o),mul=1+o.plus*.14;if(d.atk){b.atkMin+=d.atk[0]*mul;b.atkMax+=d.atk[1]*mul}for(let k of ['matk','def','mdef'])b[k]+=(d[k]||0)*mul;for(let k of ['crit','accuracy','evasion','speed','hp','mp'])b[k]+=d[k]||0});player.stats={...s,...b};player.maxHp=Math.round(c.hp+player.level*(player.classId==='knight'?28:17)+s.vit*7+b.hp);player.maxMp=Math.round(c.mp+player.level*(c.ranged?14:9)+s.spi*5+b.mp);if(fill){player.hp=player.maxHp;player.mp=player.maxMp}else{player.hp=Math.min(player.hp,player.maxHp);player.mp=Math.min(player.mp,player.maxMp)}updateHUD()}

function loadGLTF(url){return new Promise((res,rej)=>glLoader.load(url,g=>res(g),undefined,rej))}function loadFBX(url){return new Promise((res,rej)=>fbxLoader.load(url,res,undefined,rej))}
async function loadAssets(){const tasks=[];let done=0,total=5+4+18;const progress=t=>{$('#load-fill').style.width=`${Math.round(++done/total*100)}%`;$('#load-text').textContent=t};for(const c of Object.values(CLASSES)){tasks.push(loadGLTF(`${CHAR_DIR}${c.model}.gltf`).then(g=>{state.assets.characters[c.model]=g;progress(`Вооружаем: ${c.name}`)}))}for(const m of ['Skeleton','Slime','Bat','Dragon'])tasks.push(loadFBX(`${MON_DIR}${m}.fbx`).then(g=>{state.assets.monsters[m]=g;progress(`Пробуждаем: ${m}`)}));let worldNames=['tree','tree-crooked','tree-high','tree-high-crooked','rock-large','rock-wide','lantern','fence','fence-broken','cart','stall','stall-red','wall-arch','wall-block','wall-corner','wall-door','roof-high','fountain-round'];for(let n of worldNames)tasks.push(loadGLTF(`${WORLD_DIR}${n}.glb`).then(g=>{state.assets.world[n]=g.scene;progress('Возводим Астерхолд')}));await Promise.all(tasks)}
function prepObject(root,tint){root.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;if(o.material){o.material=o.material.clone();if(tint&&o.material.color)o.material.color.multiply(new THREE.Color(tint));o.material.roughness=.78}}});return root}
function cloneAnimated(asset,scale=1,tint){let root=SkeletonUtils.clone(asset.scene||asset);prepObject(root,tint);root.scale.setScalar(scale);let clips=asset.animations||[];return{root,clips}}
function pickClip(clips,type){let terms={idle:['idle','survey'],walk:['walk','run','flying'],attack:['sword_attack','dagger_attack','bow_shoot','attack','spell','shoot','cast'],death:['death','die']}[type]||[type];for(let t of terms){let found=clips.find(c=>c.name.toLowerCase().includes(t));if(found)return found}return clips[type==='attack'?1:0]}
function setAction(e,type,once=false){if(!e.mixer||!e.clips.length)return;let clip=pickClip(e.clips,type);if(!clip||e.actionType===type&&!once)return;let next=e.mixer.clipAction(clip);next.reset();next.enabled=true;next.setLoop(once?THREE.LoopOnce:THREE.LoopRepeat);next.clampWhenFinished=once;next.fadeIn(.14).play();if(e.action&&e.action!==next)e.action.fadeOut(.12);e.action=next;e.actionType=type}
function addEntityModel(e,kind){let source=kind==='player'||kind==='npc'?state.assets.characters[e.model]:state.assets.monsters[e.model];let obj=cloneAnimated(source,e.scale||.01,e.tint);e.mesh=obj.root;e.clips=obj.clips;e.mesh.position.set(e.x,0,e.z);e.mesh.userData.entity=e;e.mesh.traverse(o=>o.userData.entity=e);entityGroup.add(e.mesh);e.mixer=new THREE.AnimationMixer(e.mesh);state.mixers.push(e.mixer);setAction(e,'idle');if(kind==='monster')addNameplate(e);if(kind==='npc')addNpcLabel(e)}
function addNpcLabel(e){let c=document.createElement('canvas');c.width=512;c.height=80;let x=c.getContext('2d');x.textAlign='center';x.shadowColor='#000';x.shadowBlur=9;x.font='700 25px Inter';x.fillStyle='#e1c17f';x.fillText(e.name,256,31);x.font='18px Inter';x.fillStyle='#b9afa0';x.fillText({elder:'Задание',smith:'Кузница',shop:'Торговля',teleport:'Переход'}[e.role],256,59);let tex=new THREE.CanvasTexture(c),s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));s.scale.set(5.4,.84,1);s.position.y=3.4;s.renderOrder=20;e.mesh.add(s)}
