function refreshNameplate(e){if(!e.nameCtx)return;let x=e.nameCtx;x.clearRect(0,0,512,96);x.font=`700 ${e.boss?29:25}px Inter`;x.textAlign='center';x.fillStyle=e.boss?'#efb4a0':'#e8e0d0';x.shadowColor='#000';x.shadowBlur=8;x.fillText(e.name,256,35);x.fillStyle='#090b0c';x.fillRect(96,56,320,14);x.fillStyle=e.boss?'#b63339':'#7f242b';x.fillRect(99,59,314*clamp(e.hp/e.maxHp,0,1),8);e.nameSprite.material.map.needsUpdate=true}

function worldModel(name,x,z,s=1,rot=0,tint){let src=state.assets.world[name];if(!src)return;let o=src.clone(true);prepObject(o,tint);o.position.set(x,0,z);o.rotation.y=rot;o.scale.setScalar(s);worldGroup.add(o);return o}
function buildWorld(){worldGroup.clear();for(let i=0;i<65;i++){let forest=i>28,x=forest?rand(12,47):rand(-43,25),z=forest?rand(5,36):rand(-31,19);if(Math.hypot(x+8,z+5)<10)continue;worldModel(['tree','tree-crooked','tree-high','tree-high-crooked'][i%4],x,z,rand(1.1,2.2),rand(0,6.28),forest?0x879b83:0x9aa38c)}for(let i=0;i<28;i++)worldModel(i%2?'rock-large':'rock-wide',rand(-46,48),rand(-35,37),rand(.7,1.7),rand(0,6.28),0x8b918b);buildTown(-27,-19,1.5);buildTown(-7,-5,1);for(let i=0;i<8;i++)worldModel(i%3?'fence':'fence-broken',-14+i*2.2,-7+i*.22,1,0);for(let p of [[-10,-4],[-4,-7],[-25,-16],[-30,-22],[19,7],[35,25]]){let l=worldModel('lantern',p[0],p[1],1.4);if(l){let light=new THREE.PointLight(0xff8b35,5.5,10,2);light.position.set(0,2.6,0);l.add(light)}}let mine=worldModel('wall-arch',39,31,3.2,Math.PI,0x59605d);for(let i=0;i<6;i++)worldModel('rock-large',35+rand(0,8),27+rand(0,8),rand(1.5,2.4),rand(0,6.28),0x5f615d)}
function buildTown(x,z,s){for(let i=0;i<7;i++){let a=i/7*Math.PI*2,r=5*s;worldModel('wall-block',x+Math.cos(a)*r,z+Math.sin(a)*r,1.5*s,-a,0xb0a999)}worldModel('wall-arch',x,z+5*s,1.8*s,0,0xb0a999);worldModel('roof-high',x-2*s,z-1*s,2*s,.2,0x8c6c61);worldModel('roof',x+2.5*s,z-1.4*s,1.7*s,-.2,0x79524a);worldModel('fountain-round',x,z,1.5*s);worldModel('stall-red',x+3*s,z+2*s,1.2*s,-1);worldModel('cart',x-3*s,z+1.5*s,1.1*s,.5)}
function spawnEntities(){state.entities.forEach(e=>e.mesh&&entityGroup.remove(e.mesh));state.entities=[];state.mixers=[];let c=CLASSES[player.classId];state.playerEntity={kind:'player',model:c.model,scale:.72,x:player.x,z:player.z,tint:0xffffff};addEntityModel(state.playerEntity,'player');let npcs=[['Староста Роэн','Warrior',-7,-2.5,'elder'],['Кузнец Бран','Warrior',-10,-6,'smith'],['Торговка Эльза','Ranger',-4.8,-5,'shop'],['Проводник Каэль','Wizard',-7.5,-8,'teleport']];npcs.forEach(([name,model,x,z,role])=>{let e={kind:'npc',name,model,x,z,role,scale:.7,tint:role==='smith'?0xc9875c:0xffffff};addEntityModel(e,'npc');state.entities.push(e)});let types=['wolf','exile','spider','undead','bat','cultist','miner','wraith'];for(let i=0;i<36;i++){let forest=i>=17,x=forest?rand(13,34):rand(1,17),z=forest?rand(4,24):rand(-2,15);spawnMonster(types[i%types.length],x,z)}spawnMonster('mini',26,5);spawnMonster('big',39,32)}
function spawnMonster(id,x,z,delay=0){let d=MONSTERS[id],e={kind:'monster',id,name:d.name,model:d.model,level:d.level,boss:d.boss,hp:d.hp,maxHp:d.hp,atk:d.atk,baseAtk:d.atk,phase:1,x,z,homeX:x,homeZ:z,scale:d.scale*.01,tint:d.tint,alive:delay<=0,respawn:delay,attackCd:rand(0,1),hitFlash:0,status:{}};addEntityModel(e,'monster');e.mesh.visible=e.alive;state.entities.push(e);return e}

async function startGame(load=false){initAudio();$('#start-screen').classList.add('hidden');$('#loading').classList.remove('hidden');if(load){try{let s=JSON.parse(localStorage.getItem(SAVE_KEY));player=s.player;state.quest=s.quest||0;state.kills=s.kills||0;state.bossKills=s.bossKills||0;state.lootBuffer=s.lootBuffer||[];state.settings={...state.settings,...s.settings};state.selectedClass=player.classId}catch{newPlayer()}}else newPlayer();await loadAssets();buildWorld();spawnEntities();applySettings();$('#loading').classList.add('hidden');$('#hud').classList.remove('hidden');state.started=true;buildHotbar();updateQuest();recalc(load?false:true);log(`Добро пожаловать в Варендор, ${player.name}.`,'system');log('ЛКМ — путь и цель. Space — атака. 1–4 — навыки.','system');canvas.focus();saveGame()}
